import { properties, search as searchNuclides, findByNumbers, CONSTANTS } from './physics.mjs';

const $ = id => document.getElementById(id);
const names = ['Neutron','Hydrogen','Helium','Lithium','Beryllium','Bor','Kulstof','Nitrogen','Oxygen','Fluor','Neon','Natrium','Magnesium','Aluminium','Silicium','Fosfor','Svovl','Chlor','Argon','Kalium','Calcium','Scandium','Titan','Vanadium','Chrom','Mangan','Jern','Cobalt','Nikkel','Kobber','Zink','Gallium','Germanium','Arsen','Selen','Brom','Krypton','Rubidium','Strontium','Yttrium','Zirconium','Niobium','Molybdæn','Technetium','Ruthenium','Rhodium','Palladium','Sølv','Cadmium','Indium','Tin','Antimon','Tellur','Iod','Xenon','Cæsium','Barium','Lanthan','Cerium','Praseodym','Neodym','Promethium','Samarium','Europium','Gadolinium','Terbium','Dysprosium','Holmium','Erbium','Thulium','Ytterbium','Lutetium','Hafnium','Tantal','Wolfram','Rhenium','Osmium','Iridium','Platin','Guld','Kviksølv','Thallium','Bly','Bismuth','Polonium','Astat','Radon','Francium','Radium','Actinium','Thorium','Protactinium','Uran','Neptunium','Plutonium','Americium','Curium','Berkelium','Californium','Einsteinium','Fermium','Mendelevium','Nobelium','Lawrencium','Rutherfordium','Dubnium','Seaborgium','Bohrium','Hassium','Meitnerium','Darmstadtium','Røntgenium','Copernicium','Nihonium','Flerovium','Moscovium','Livermorium','Tenness','Oganesson'];
let rows=[], meta, selected, pinned=null, graph=false, width=1,height=1,scale=1,baseScale=1,originX=0,originY=0,maxN=180,maxZ=118,frame=0;
let matches=[], toastTimer;
const map = new Map(), canvas=$('chart'), ctx=canvas.getContext('2d');
const pointers=new Map(); let gesture=null;
function escape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function fmt(value){if(value===null||!Number.isFinite(value))return 'Utilgængelig';const digits=Number($('digits').value);if(value!==0&&Math.abs(value)<10**(-digits))return value.toExponential(Math.min(digits,5)).replace('.',',');return $('format').value==='significant'?Number(value.toPrecision(digits)).toLocaleString('da-DK',{maximumSignificantDigits:digits}):value.toLocaleString('da-DK',{minimumFractionDigits:digits,maximumFractionDigits:digits});}
function notation(r){return `<span class="numbers"><span>${r.a}</span><span>${r.z}</span></span>${escape(r.symbol)}`;}
function label(r){return `${names[r.z]||r.symbol}-${r.a}`;}
function halfLife(r){if(r.stable)return 'Stabil';if(!r.halfLife)return 'Utilgængelig';if(r.halfLife==='p-unst')return 'Partikelustabil';return `${r.halfLife.replace('#',' (est.)')} ${r.halfLifeUnit}`.trim();}
function category(r){if(r.stable)return 'stable';const d=(r.decay||'').split(';').map(s=>s.trim()).find(s=>!s.startsWith('IS='))||'';if(/^B-/.test(d))return 'minus';if(/^(B\+|EC)/.test(d))return 'plus';if(/^A(?:=|~|>|<)/.test(d))return 'alpha';return 'other';}
function palette(){const s=getComputedStyle(document.documentElement);return Object.fromEntries(['text','muted','accent','grid','card','stable','minus','plus','alpha','other'].map(k=>[k,s.getPropertyValue('--'+k).trim()]));}
function schedule(){if(!frame)frame=requestAnimationFrame(()=>{frame=0;draw();});}
function fit(){baseScale=Math.min((width-105)/(maxN+3),(height-75)/(maxZ+3));scale=baseScale;originX=55;originY=height-40;hideTip();schedule();}
function resize(){const rect=$('stage').getBoundingClientRect();width=rect.width;height=rect.height;const dpr=window.devicePixelRatio||1;canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);fit();}
function zoom(factor,x=width/2,y=height/2){if(graph)return;const next=Math.max(baseScale*.7,Math.min(55,scale*factor));originX=x-(x-originX)*next/scale;originY=y-(y-originY)*next/scale;scale=next;hideTip();schedule();}
function focus(r){if(graph){schedule();return;}scale=Math.min(38,Math.max(baseScale*5,32));originX=width/2-(r.n+.5)*scale;originY=height/2+(r.z+.5)*scale;hideTip();schedule();}
function draw(){const p=palette();ctx.clearRect(0,0,width,height);if(graph){drawGraph(p);return;}const stableOnly=$('stable-only').checked;
 ctx.save();ctx.beginPath();ctx.rect(44,12,width-50,height-46);ctx.clip();
 const step=scale>12?5:scale>5?10:20;ctx.strokeStyle=p.grid;ctx.lineWidth=.6;
 for(let n=0;n<=maxN+10;n+=step){const x=originX+n*scale;ctx.beginPath();ctx.moveTo(x,12);ctx.lineTo(x,height-35);ctx.stroke();}
 for(let z=0;z<=maxZ+5;z+=step){const y=originY-z*scale;ctx.beginPath();ctx.moveTo(44,y);ctx.lineTo(width,y);ctx.stroke();}
 for(const r of rows){const x=originX+r.n*scale,y=originY-(r.z+1)*scale;if(x>width||x+scale<44||y>height-34||y+scale<12)continue;ctx.globalAlpha=stableOnly&&!r.stable?.15:1;ctx.fillStyle=p[category(r)];const gap=scale>5?1.1:.3;ctx.fillRect(x+gap/2,y+gap/2,Math.max(.4,scale-gap),Math.max(.4,scale-gap));
 if(scale>=20){ctx.globalAlpha=stableOnly&&!r.stable?.15:1;ctx.fillStyle='#13221b';
 // Conventional notation: mass number above proton number, left of the symbol.
 let symbolSize=scale*.53,numberSize=scale*.29;const gap=scale*.035;
 ctx.font=`600 ${numberSize}px system-ui`;
 let numberWidth=Math.max(ctx.measureText(String(r.a)).width,ctx.measureText(String(r.z)).width);
 ctx.font=`italic 600 ${symbolSize}px Georgia, serif`;
 let symbolWidth=ctx.measureText(r.symbol).width;
 const shrink=Math.min(1,scale*.88/(numberWidth+gap+symbolWidth));
 symbolSize*=shrink;numberSize*=shrink;numberWidth*=shrink;symbolWidth*=shrink;
 const left=x+(scale-numberWidth-gap-symbolWidth)/2;
 ctx.textBaseline='middle';ctx.textAlign='right';ctx.font=`600 ${numberSize}px system-ui`;
 ctx.fillText(String(r.a),left+numberWidth,y+scale*.31);
 ctx.fillText(String(r.z),left+numberWidth,y+scale*.69);
 ctx.textAlign='left';ctx.font=`italic 600 ${symbolSize}px Georgia, serif`;
 ctx.fillText(r.symbol,left+numberWidth+gap,y+scale*.51);
 ctx.textBaseline='alphabetic';}}
 ctx.globalAlpha=1;
 for(const [r,color] of [[pinned,p.alpha],[selected,p.text]])if(r){const x=originX+r.n*scale,y=originY-(r.z+1)*scale;ctx.strokeStyle=color;ctx.lineWidth=2;ctx.strokeRect(x-1,y-1,scale+2,scale+2);if(scale<15){ctx.beginPath();ctx.arc(x+scale/2,y+scale/2,7,0,Math.PI*2);ctx.stroke();}}
 ctx.restore();ctx.fillStyle=p.muted;ctx.font='10px system-ui';ctx.textAlign='center';
 for(let n=0;n<=maxN;n+=step){const x=originX+(n+.5)*scale;if(x>50&&x<width-18)ctx.fillText(n,x,height-25);}
 ctx.textAlign='right';for(let z=0;z<=maxZ;z+=step){const y=originY-(z+.5)*scale;if(y>15&&y<height-40)ctx.fillText(z,37,y+3);}
 $('zoom-label').textContent=Math.round(scale/baseScale*100)+' %';
}
function graphPosition(r){const p=properties(r);return {x:58+r.a/300*(width-85),y:height-42-(p.perA??0)/9.2*(height-72)};}
function drawGraph(p){ctx.font='10px system-ui';ctx.strokeStyle=p.grid;ctx.fillStyle=p.muted;for(let e=0;e<=9;e++){let y=height-42-e/9.2*(height-72);ctx.beginPath();ctx.moveTo(52,y);ctx.lineTo(width-20,y);ctx.stroke();ctx.textAlign='right';ctx.fillText(e,40,y+3);}for(let a=0;a<=300;a+=50){const x=58+a/300*(width-85);ctx.textAlign='center';ctx.fillText(a,x,height-25);}for(const r of rows){const pr=properties(r);if(pr.perA===null||pr.perA<0)continue;const {x,y}=graphPosition(r);ctx.globalAlpha=$('stable-only').checked&&!r.stable?.1:r.massEstimated?.25:.7;ctx.fillStyle=p[category(r)];ctx.beginPath();ctx.arc(x,y,r.stable?2.6:1.5,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;if(selected){const {x,y}=graphPosition(selected);ctx.strokeStyle=p.text;ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,6,0,Math.PI*2);ctx.stroke();ctx.fillStyle=p.text;ctx.textAlign='left';ctx.fillText(selected.symbol+'-'+selected.a,Math.min(x+10,width-65),Math.max(20,y-10));}$('zoom-label').textContent='MeV / nukleon';}
function pick(x,y){if(x<44||y>height-34)return null;if(graph){let closest=null,dist=100;for(const r of rows){const p=properties(r);if(p.perA===null||p.perA<0)continue;const pos=graphPosition(r),d=(pos.x-x)**2+(pos.y-y)**2;if(d<dist){dist=d;closest=r;}}return closest;}return map.get(`${Math.floor((x-originX)/scale)},${Math.floor((originY-y)/scale)}`)||null;}
function hideTip(){$('tooltip').hidden=true;}
function showTip(r,x,y){if(!r){hideTip();return;}$('tooltip').innerHTML=`<strong>${escape(label(r))}</strong><br><span>${r.a}${escape(r.symbol)} · Z ${r.z} · N ${r.n} · ${r.stable?'Stabil':'Radioaktiv'}</span>`;$('tooltip').style.left=Math.max(10,Math.min(x+16,width-225))+'px';$('tooltip').style.top=Math.max(10,Math.min(y+16,height-65))+'px';$('tooltip').hidden=false;}
function select(r,move=false){selected=r;renderPanel();renderComparison();$('selection-caption').textContent=`${label(r)} · ${r.a} nukleoner`;if(move)focus(r);else schedule();}
function renderPanel(){if(!selected)return;const r=selected,p=properties(r),siblings=rows.filter(x=>x.z===r.z),index=siblings.indexOf(r);
 $('info').innerHTML=`<div class="panel-heading"><span class="tiny-label">VALGT NUKLID</span><span class="status">${r.stable?'● Stabil':r.halfLife?'Radioaktiv':'Stabilitet ukendt'}</span></div><div class="nuclide-symbol" aria-label="${r.a}, atomnummer ${r.z}, ${escape(r.symbol)}">${notation(r)}</div><h2>${escape(label(r))}</h2><div class="isotope-navigation"><button id="prev" aria-label="Forrige isotop" ${index===0?'disabled':''}>←</button><span>${index+1} af ${siblings.length} isotoper</span><button id="next" aria-label="Næste isotop" ${index===siblings.length-1?'disabled':''}>→</button></div>
 <div class="particle-grid"><div><strong>${r.z}</strong><span>PROTONER · Z</span></div><div><strong>${r.n}</strong><span>NEUTRONER · N</span></div><div><strong>${r.a}</strong><span>NUKLEONER · A</span></div></div>
 <div class="energy-box"><label>Samlet bindingsenergi · E<sub>b</sub></label><strong>${fmt(p.total)}</strong><small>MeV</small>${r.bindingUncertainty!==null?`<span class="uncertainty">± ${fmt(r.bindingUncertainty*r.a)} MeV</span>`:''}</div>
 <div class="energy-box secondary"><label>Bindingsenergi pr. nukleon · E<sub>b</sub> / A</label><strong>${fmt(p.perA)}</strong><small>MeV/nukleon</small>${r.bindingUncertainty!==null?`<span class="uncertainty">± ${fmt(r.bindingUncertainty)} MeV/nukleon</span>`:''}</div>
 <dl class="details"><div><dt>Atommasse</dt><dd>${fmt(r.mass)} u${r.massUncertainty!==null?`<span class="uncertainty">± ${fmt(r.massUncertainty)} u</span>`:''}</dd></div><div><dt>Massedefekt</dt><dd>${fmt(p.defect)} u</dd></div><div><dt>Halveringstid</dt><dd>${escape(halfLife(r))}${r.halfLifeUncertainty?`<span class="uncertainty">Usikkerhed: ${escape(r.halfLifeUncertainty)} ${escape(r.halfLifeUnit)}</span>`:''}</dd></div></dl>
 <p class="data-quality">${r.massEstimated?'<span class="estimated">◇ Masse estimeret fra systematik (#)</span>':'● Masse eksperimentelt bestemt / evalueret'}<br>${p.evaluated?'Bindingsenergi: evalueret AME2020-værdi':'Bindingsenergi: beregnet fra atommasse'}${r.bindingEstimated?' · estimeret (#)':''}</p>
 <div class="panel-actions"><button id="copy">Kopiér værdier ↗</button><button id="compare">${pinned?'Sammenlign her':'Sammenlign +'} </button></div>
 <details><summary>Se beregning og konstanter</summary><p>Neutrale atommasser holder elektronmasserne konsistente. Der afrundes kun ved visning.</p><div class="formula">Δm = Z × m(¹H) + N × mₙ − m_atom<br>= ${r.z} × ${CONSTANTS.hydrogen} + ${r.n} × ${CONSTANTS.neutron} − ${r.mass}<br>= ${fmt(p.defect)} u<br><br>E_b = Δm × ${CONSTANTS.mevPerU}<br>= ${fmt(p.calculated)} MeV<br>E_b / A = ${fmt(p.calculated===null?null:p.calculated/r.a)} MeV/nukleon</div><p>Panelet foretrækker AME2020's evaluerede E_b/A. Samlet E_b = (E_b/A) × A. Forskel (beregnet − evalueret): ${fmt(p.delta)} MeV. AME2020 bruger sine egne evaluerede hydrogen- og neutronmasser; de afviger lidt fra konstanterne ovenfor. Også tabelpræcision spiller ind. Usikkerhederne er fra AME, ikke en uafhængig fejlberegning.</p><p>Masseoverskud fra AME: ${fmt(r.massExcess)} keV. Det er (m_atom − A u)c² og må ikke forveksles med massedefekt.</p><button id="copy-formula" class="text-button">Kopiér beregning til Word ↗</button></details>
 <details><summary>Henfald og originaldata</summary><p>${escape(r.decay||'Henfaldsdata utilgængelige')}</p><p>Spin / paritet: ${escape(r.spin||'Utilgængelig')}. Notation og usikkerheder gengives fra NUBASE2020, inklusive grænser og systematikmarkører.</p><p><a href="data/raw/mass_1.mas20.txt" target="_blank">AME2020</a>: linje ${r.ameLine??'—'}<br><a href="data/raw/nubase_4.mas20.txt" target="_blank">NUBASE2020</a>: linje ${r.nubaseLine??'—'}</p></details><div class="source-lines">AME2020 / NUBASE2020 · Grundtilstand</div>`;
 $('prev').onclick=()=>select(siblings[index-1],true);$('next').onclick=()=>select(siblings[index+1],true);
 $('copy').onclick=()=>copy(valuesText(r));$('copy-formula').onclick=()=>copy(valuesText(r)+`\n\nΔm = Z × m(¹H) + N × mₙ − m_atom\n= ${r.z} × ${CONSTANTS.hydrogen} + ${r.n} × ${CONSTANTS.neutron} − ${r.mass} = ${fmt(p.defect)} u\nE_b = Δm × ${CONSTANTS.mevPerU} = ${fmt(p.calculated)} MeV\nE_b/A = ${fmt(p.calculated/r.a)} MeV/nukleon\nEvalueret E_b fra AME foretrækkes; forskel: ${fmt(p.delta)} MeV.`);
 $('compare').onclick=()=>{if(!pinned){pinned=r;toast('Vælg en anden nuklid for at sammenligne.');}else if(pinned===r){toast('Vælg en anden nuklid i kortet eller søgningen.');}renderPanel();renderComparison();schedule();};
}
function valuesText(r){const p=properties(r);return `${label(r)} (${r.a}${r.symbol}, Z=${r.z})\nProtonantal: ${r.z}\nNeutronantal: ${r.n}\nMassetal: ${r.a}\nAtommasse: ${fmt(r.mass)} u\nMasseusikkerhed: ± ${fmt(r.massUncertainty)} u\nMassedefekt: ${fmt(p.defect)} u\nSamlet bindingsenergi: ${fmt(p.total)} MeV\nBindingsenergi pr. nukleon: ${fmt(p.perA)} MeV/nukleon\nHalveringstid: ${halfLife(r)}\nMasse: ${r.massEstimated?'estimeret fra systematik':'eksperimentelt bestemt / evalueret'}\nKilde: AME2020 (linje ${r.ameLine}) og NUBASE2020 (linje ${r.nubaseLine})\nhttps://www-nds.iaea.org/amdc/`;
}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Kopieret med enheder og kilde.');}catch{const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();const success=document.execCommand('copy');area.remove();toast(success?'Kopieret med enheder og kilde.':'Kunne ikke kopiere. Tillad adgang til udklipsholderen.');}}
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function renderComparison(){if(!pinned){$('comparison').hidden=true;return;}$('comparison').hidden=false;const other=selected===pinned?null:selected;const value=(r,key,unit='')=>r?fmt(properties(r)[key])+' '+unit:'Vælg en anden nuklid';$('comparison').innerHTML=`<div class="comparison-heading"><h2>Sammenlign to nuklider</h2><button id="clear-compare">Luk ×</button></div><table><thead><tr><th>Egenskab</th><th>${escape(label(pinned))}</th><th>${other?escape(label(other)):'Vælg en anden nuklid'}</th></tr></thead><tbody><tr><td>Protoner / neutroner</td><td>${pinned.z} / ${pinned.n}</td><td>${other?other.z+' / '+other.n:'—'}</td></tr><tr><td>Samlet bindingsenergi</td><td>${value(pinned,'total','MeV')}</td><td>${value(other,'total','MeV')}</td></tr><tr><td>Bindingsenergi pr. nukleon</td><td>${value(pinned,'perA','MeV/nukleon')}</td><td>${value(other,'perA','MeV/nukleon')}</td></tr><tr><td>Atommasse</td><td>${fmt(pinned.mass)} u</td><td>${other?fmt(other.mass)+' u':'—'}</td></tr><tr><td>Halveringstid</td><td>${escape(halfLife(pinned))}</td><td>${other?escape(halfLife(other)):'—'}</td></tr></tbody></table>`;$('clear-compare').onclick=()=>{pinned=null;renderComparison();renderPanel();schedule();};}
$('number-search').addEventListener('submit',e=>{
 e.preventDefault();
 const a=Number($('mass-number').value),z=Number($('proton-number').value);
 if(!rows.length){$('number-feedback').textContent='Vent, indtil kernedata er indlæst.';return;}
 if(z>a){$('number-feedback').textContent='Protontallet Z kan ikke være større end massetallet A.';return;}
 const r=findByNumbers(rows,$('mass-number').value,$('proton-number').value);
 if(!r){$('number-feedback').textContent=`Ingen nuklid med A = ${a} og Z = ${z} i datasættet.`;return;}
 select(r,true);$('results').hidden=true;
 $('number-feedback').textContent=`${label(r)} fundet · ${r.z} protoner og ${r.n} neutroner.`;
});
for(const id of ['mass-number','proton-number'])$(id).addEventListener('input',()=>{$('number-feedback').textContent='';});
function renderResults(){matches=searchNuclides(rows,$('search').value,names);const q=$('search').value.trim();$('results').hidden=!q;if(!q)return;$('results').innerHTML=`<div class="result-summary">${matches.length?matches.length+' isotop'+(matches.length===1?'':'er')+' fundet':'Ingen nuklider fundet. Prøv Mg, Magnesium, Mg-24 eller Z = 12.'}</div>`+matches.map((r,i)=>`<button data-result="${i}"><span><strong>${r.a}${escape(r.symbol)}</strong> · ${escape(label(r))}</span><small>${r.stable?'Stabil':escape(halfLife(r))}</small></button>`).join('');$('results').querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{select(matches[Number(b.dataset.result)],true);$('results').hidden=true;$('search').value='';});}
$('search').addEventListener('input',renderResults);$('search').addEventListener('focus',()=>{if($('search').value)renderResults();});$('search').addEventListener('keydown',e=>{if(e.key==='Escape'){$('results').hidden=true;$('search').blur();}if(e.key==='ArrowDown'){e.preventDefault();$('results').querySelector('button')?.focus();}if(e.key==='Enter'&&matches.length){select(matches[0],true);$('results').hidden=true;$('search').value='';}});
$('results').addEventListener('keydown',e=>{const buttons=[...$('results').querySelectorAll('button')],idx=buttons.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[Math.max(0,Math.min(buttons.length-1,idx+(e.key==='ArrowDown'?1:-1)))]?.focus();}if(e.key==='Escape'){$('results').hidden=true;$('search').focus();}});
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('results').hidden=true;});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('search').focus();}});
for(const id of ['digits','format'])$(id).onchange=()=>{renderPanel();renderComparison();};
$('theme').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('kernekort-theme',theme);}catch{}schedule();};
try{document.documentElement.dataset.theme=localStorage.getItem('kernekort-theme')||'dark';}catch{}
$('stable-only').onchange=schedule;$('zoom-in').onclick=()=>zoom(1.65);$('zoom-out').onclick=()=>zoom(1/1.65);$('reset').onclick=fit;$('focus').onclick=()=>selected&&focus(selected);
function setGraph(value){graph=value;$('chart-tab').classList.toggle('active',!graph);$('graph-tab').classList.toggle('active',graph);$('axis-x').textContent=graph?'MASSETAL · A':'NEUTRONANTAL · N';document.querySelector('.axis-y').textContent=graph?'BINDINGSENERGI · MeV/nukleon':'PROTONANTAL · Z';for(const id of ['zoom-in','zoom-out','reset','focus'])$(id).disabled=graph;hideTip();schedule();}
$('chart-tab').onclick=()=>setGraph(false);$('graph-tab').onclick=()=>setGraph(true);
document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>{const r=searchNuclides(rows,b.dataset.quick,names)[0];if(r)select(r,true);});
$('source-details').onclick=()=>{$('source-content').hidden=!$('source-content').hidden;};
function point(e){const r=canvas.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top};}
canvas.addEventListener('wheel',e=>{if(graph)return;e.preventDefault();const p=point(e);const delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?height:1);zoom(Math.exp(Math.max(-1,Math.min(1,-delta*.0035))),p.x,p.y);},{passive:false});
canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);const p=point(e);pointers.set(e.pointerId,p);hideTip();if(pointers.size===1)gesture={start:p,last:p,moved:false};else{gesture.moved=true;const [a,b]=[...pointers.values()];gesture.distance=Math.hypot(a.x-b.x,a.y-b.y);}});
canvas.addEventListener('pointermove',e=>{const p=point(e);if(!pointers.has(e.pointerId)){showTip(pick(p.x,p.y),p.x,p.y);return;}pointers.set(e.pointerId,p);if(pointers.size===2){const [a,b]=[...pointers.values()],distance=Math.hypot(a.x-b.x,a.y-b.y);if(gesture.distance)zoom((distance/gesture.distance)**1.35,(a.x+b.x)/2,(a.y+b.y)/2);gesture.distance=distance;gesture.moved=true;return;}if(Math.hypot(p.x-gesture.start.x,p.y-gesture.start.y)>4)gesture.moved=true;if(gesture.moved&&!graph){originX+=p.x-gesture.last.x;originY+=p.y-gesture.last.y;schedule();}gesture.last=p;});
canvas.addEventListener('pointerup',e=>{const p=point(e);if(gesture&&!gesture.moved){const r=pick(p.x,p.y);if(r)select(r);}pointers.delete(e.pointerId);if(pointers.size){const remaining=[...pointers.values()][0];gesture={start:remaining,last:remaining,moved:true};}else gesture=null;});
canvas.addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);gesture=null;});canvas.addEventListener('pointerleave',hideTip);
canvas.addEventListener('keydown',e=>{if(e.key==='+'||e.key==='='){e.preventDefault();zoom(1.65);}if(e.key==='-'){e.preventDefault();zoom(1/1.65);}if(e.key==='Home'){e.preventDefault();fit();}if(selected&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const dn=e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0,dz=e.key==='ArrowUp'?1:e.key==='ArrowDown'?-1:0;for(let i=1;i<30;i++){const r=map.get(`${selected.n+dn*i},${selected.z+dz*i}`);if(r){select(r,true);break;}}}});
new ResizeObserver(resize).observe($('stage'));
try{const response=await fetch('data/nuclides.json');if(!response.ok)throw new Error('Databasen kunne ikke hentes');const data=await response.json();rows=data.nuclides;meta=data.meta;for(const r of rows)map.set(`${r.n},${r.z}`,r);maxN=Math.max(...rows.map(r=>r.n));maxZ=Math.max(...rows.map(r=>r.z));$('count').textContent=rows.length.toLocaleString('da-DK');$('estimated-count').textContent=rows.filter(r=>r.massEstimated).length.toLocaleString('da-DK')+' estimerede masser';$('source-content').innerHTML=`<p>${escape(meta.version)} · ${rows.length} nuklider. ${escape(meta.scope)} Datatabellerne er udgivet i 2021; dette er en fast 2020-evaluering, ikke et løbende opdateret LiveChart. Importeret: ${escape(meta.importedAt.slice(0,10))}.</p><p>IAEA LiveChart tilbyder et CSV-API til grundtilstande. Denne hjemmeside bruger i stedet de versionsfastlagte AMDC-filer, så alle værdier kan spores og bruges lokalt. Ingen masseværdier syntetiseres.</p>${meta.sources.map(s=>`<a href="${escape(s.url)}" target="_blank" rel="noopener">${escape(s.file)} ↗</a><div class="hash">SHA-256: ${escape(s.sha256)}</div>`).join('')}<p>${meta.citations.map(escape).join('<br>')}</p><p># angiver estimat fra systematik. Henfaldsfarven viser første henfaldskanal i NUBASE, ikke alle mulige kanaler. Halveringstider og deres enheder gengives som i kilden (y = år, d = døgn, h = timer). Isomerer er ikke medtaget. Neutronen (Z = 0) følger med originaltabellen.</p>`;$('loading').hidden=true;fit();select(searchNuclides(rows,'Mg-24',names)[0]);}
catch(error){$('loading').textContent='Data kunne ikke indlæses. Start med npm start, og åbn http://localhost:4173. '+error.message;$('info').textContent='Kernedata er utilgængelige. Der vises ingen gættede værdier.';}


